  public void ShowOptions(){if(utilityTray!=null)utilityTray.Visible=false;Keyboard.ReleaseAll();optionsWorkspace.Visible=true;tabs.Visible=false;optionsWorkspace.BringToFront();Language.Apply(optionsWorkspace);}
  public void ShowMainPage(int page){if(utilityTray!=null)utilityTray.Visible=false;optionsWorkspace.Visible=false;tabs.Visible=true;tabs.SelectedIndex=page;tabs.BringToFront();ActiveControl=null;}
  public void SetLoopView(bool inferno){Engine.System.SceneMode=inferno;scene.Visible=inferno;loopDeck.Visible=!inferno;if(inferno)scene.BringToFront();}
  Button Btn(string text,int width,Action action){Button b=Theme.Button(text,action);b.Width=width;return b;}
  TabPage Page(string title){TabPage p=new TabPage(title){BackColor=Theme.Background,ForeColor=Theme.Text,Padding=new Padding(0)};tabs.TabPages.Add(p);return p;}
  void Change(Action a){lock(Engine.Gate){a();Engine.Dirty=true;}}
  void Tick(object sender,EventArgs args){if(closing)return;RefreshHardware();if(Language.English&&++languageTick%12==0)Language.Apply(this);if(scene!=null&&scene.Visible)scene.Invalidate();foreach(TrackStrip s in strips)s.RefreshState();inputBar.RefreshModel();trackBar.RefreshModel();if(!bpm.Focused){refreshing=true;bpm.Value=(decimal)MathX.Clamp(Engine.Config.Bpm,20,300);refreshing=false;}rhythmPage.Tick();settingsPage.Tick();record.ForeColor=Audio.Recorder.Recording?Theme.Red:Theme.Text;record.Text=Audio.Recorder.Recording?"■ REC "+(Audio.Recorder.Frames/44100.0).ToString("0")+"s":"● MASTER";status.Text=Language.T(RecordingCue()+(busy?"Trabajando…   ":"")+Engine.Status+"   |   IN "+(int)(Engine.InputPeak*100)+"%   OUT "+(int)(Engine.OutputPeak*100)+"%   |   Latencia estimada "+(Engine.AutomaticLatencyFrames/44.1).ToString("0")+" ms   Cortes de salida "+Audio.OutputGaps+"   |   "+((int)(Engine.Beat/Engine.BarBeats)+1)+"."+((int)(Engine.Beat%Engine.BarBeats)+1)+"   |   "+(Engine.Dirty?"Cambios sin guardar":"Sesión guardada")+(Audio.Recorder.Error==null?"":"   |   "+Audio.Recorder.Error));}
  public void ApplyLanguage(){Language.Set(Engine.System.Language);if(fxPage!=null)fxPage.RefreshModel();refreshing=true;sessionName.Text=Language.SessionName(Engine.Config.Name);refreshing=false;tooltip.SetToolTip(countIn,Language.T("La cuenta previa suena automáticamente antes de grabar."));tooltip.SetToolTip(record,Language.T("Graba la mezcla final, con efectos, en un WAV de 32 bits float."));Language.Apply(this);settingsPage.KeyboardOptions.Reload();Invalidate(true);}
  public void ApplyAppearance(){Theme.Configure(Engine.System);Theme.ApplyTree(this);foreach(TrackStrip strip in strips)strip.RefreshState();inputBar.RefreshModel();trackBar.RefreshModel();Language.Apply(this);if(lcd!=null){lcd.BackColor=Color.FromArgb(29,36,119);memory.BackColor=lcd.BackColor;memory.ForeColor=Color.White;sessionName.BackColor=lcd.BackColor;sessionName.ForeColor=Color.White;}}
  public void RefreshModel(){refreshing=true;sessionName.Text=Language.SessionName(Engine.Config.Name);memory.Value=Engine.Config.Memory;bpm.Value=(decimal)Engine.Config.Bpm;quantize.Checked=Engine.Config.Quantize;auto.Checked=Engine.Config.AutoRecord;single.Checked=Engine.Config.SinglePlay;countIn.SelectedIndex=Engine.Config.CountInBars;refreshing=false;if(fxPage!=null)fxPage.RefreshModel();if(rhythmPage!=null)rhythmPage.RefreshModel();if(settingsPage!=null)settingsPage.RefreshModel();}
  void Tap(){DateTime now=DateTime.UtcNow;double secs=(now-tap).TotalSeconds;if(secs>.2&&secs<3)Engine.SetTempo((float)(60/secs));tap=now;}
  public void StartDevices(){try{Audio.Start();}catch(Exception ex){Engine.Status=ex.Message;UiMessage.Show(ex.Message+"\n\nAbre OPCIONES → Dispositivos para elegir otro dispositivo o Sin entrada.","Configuración de audio");}try{Midi.Start();}catch(Exception ex){UiMessage.Show(ex.Message,"Configuración MIDI");}}
  public void ApplyDevices(SystemConfig config){SystemConfig old=Engine.System;Audio.Stop();Midi.Dispose();Engine.AllStop(true);Engine.System=config;try{Audio.Start();Midi.Start();Storage.SaveSystem(config);}catch(Exception e){Audio.Stop();Midi.Dispose();Engine.System=old;try{Audio.Start();Midi.Start();}catch{}throw new Exception(e.Message+" Se intentó restaurar la configuración anterior.");}}
  public void EditTrack(int index){using(TrackDialog d=new TrackDialog(Engine,index,Import,Export,RefreshModel))d.ShowDialog(this);}
  void OpenFx(bool input,int slot){(input?inputBar:trackBar).SelectSlot(slot);ShowMainPage(2);fxPage.SelectSlot(input,(input?Engine.Config.InputFx:Engine.Config.TrackFx).Bank,slot);}
  void FileMenu(){ContextMenuStrip menu=new ContextMenuStrip();menu.Items.Add("Nueva sesión",null,delegate{if(Discard()){Storage.Apply(Engine,new Snapshot{Config=new SessionConfig()});filePath=null;RefreshModel();}});menu.Items.Add("Cargar demostración de cinco pistas",null,delegate{if(!Discard())return;Snapshot demo=null;Background(delegate{demo=Demo.Create();},delegate{Storage.Apply(Engine,demo);Engine.AllStart();Engine.Dirty=false;filePath=null;RefreshModel();Engine.Status="Demo en reproducción · cinco capas de sonido propias";});});menu.Items.Add("Abrir sesión…  Ctrl+O",null,delegate{Open();});menu.Items.Add("Guardar sesión…  Ctrl+S",null,delegate{Save(false);});menu.Items.Add("Guardar como…",null,delegate{Save(true);});menu.Items.Add("Exportar mezcla con efectos…",null,delegate{ExportMix();});menu.Items.Add("Abrir carpeta de memorias",null,delegate{Directory.CreateDirectory(Storage.DataDirectory);System.Diagnostics.Process.Start("explorer.exe",Storage.DataDirectory);});Language.ApplyMenu(menu);menu.Show(Cursor.Position);}
  bool CanSave(){foreach(Track t in Engine.Tracks)if(t.State==PlayState.Recording||t.State==PlayState.Overdubbing){UiMessage.Show("Termina la grabación o sobregrabación antes de guardar o exportar.","Termina la toma");return false;}return true;}
  bool Discard(){return !Engine.Dirty||UiMessage.Show("Hay cambios sin guardar. ¿Continuar y descartarlos?","Cambiar de sesión",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes;}
  void Background(Action action,Action done){if(busy)return;busy=true;Controls[0].Enabled=false;Cursor=Cursors.WaitCursor;ThreadPool.QueueUserWorkItem(delegate{Exception error=null;try{action();}catch(Exception ex){error=ex;}if(IsDisposed)return;BeginInvoke((Action)delegate{busy=false;Controls[0].Enabled=true;Cursor=Cursors.Default;if(error!=null)UiMessage.Show(error.Message,"LoopFive");else if(done!=null)done();});});}
  void Save(bool saveAs){if(busy||!CanSave())return;string path=filePath;if(saveAs||path==null)using(SaveFileDialog d=new SaveFileDialog{Filter=Language.Filter("Sesión LoopFive|*.loop5"),FileName=Language.SessionName(Engine.Config.Name)+".loop5"}){if(d.ShowDialog(this)!=DialogResult.OK)return;path=d.FileName;}string chosen=path;Snapshot snapshot=Storage.Capture(Engine);Background(delegate{Storage.Save(chosen,snapshot);},delegate{filePath=chosen;if(Engine.Revision==snapshot.Revision)Engine.Dirty=false;Engine.Status="Sesión guardada: "+Path.GetFileName(chosen);});}
  void Open(){if(busy||!Discard())return;using(OpenFileDialog d=new OpenFileDialog{Filter=Language.Filter("Sesión LoopFive (v1 / v2)|*.loop5")})if(d.ShowDialog(this)==DialogResult.OK){string path=d.FileName;Snapshot loaded=null;Background(delegate{loaded=Storage.Load(path);},delegate{Engine.AllStop(true);Storage.Apply(Engine,loaded);filePath=path;RefreshModel();Engine.Status="Sesión abierta: "+Path.GetFileName(path);});}}
  void WriteMemory(){if(busy||!CanSave())return;int slot=(int)memory.Value;string path=Storage.MemoryPath(slot);if(File.Exists(path)&&UiMessage.Show("¿Reemplazar la memoria "+slot.ToString("00")+"? Se conservará una copia .bak.","Escribir memoria",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;Engine.Config.Memory=slot;Snapshot s=Storage.Capture(Engine);Background(delegate{Storage.Save(path,s);},delegate{if(Engine.Revision==s.Revision)Engine.Dirty=false;Engine.Status="Memoria "+slot.ToString("00")+" guardada";});}
  void RecallMemory(int slot){if(busy)return;string path=Storage.MemoryPath(slot);if(!File.Exists(path)){Engine.Status="La memoria "+slot.ToString("00")+" está vacía";return;}if(!Discard())return;Snapshot loaded=null;Background(delegate{loaded=Storage.Load(path);},delegate{Storage.Apply(Engine,loaded);Engine.Config.Memory=slot;filePath=null;RefreshModel();Engine.Status="Memoria "+slot.ToString("00")+" recuperada";});}
  public void Import(int index){if(busy)return;using(OpenFileDialog d=new OpenFileDialog{Filter=Language.Filter("Audio WAV PCM / float|*.wav")})if(d.ShowDialog(this)==DialogResult.OK){string path=d.FileName;AudioClip clip=null;float tempo=Engine.Config.Bpm;Background(delegate{clip=Wav.Read(path,tempo);},delegate{Engine.Import(index,clip);Engine.Status="WAV importado en pista "+(index+1);});}}
  public void Export(int index){if(busy||!CanSave())return;AudioClip clip;lock(Engine.Gate)clip=Engine.Tracks[index].Clip==null?null:Engine.Tracks[index].Clip.Clone();if(clip==null){UiMessage.Show("La pista está vacía.");return;}using(SaveFileDialog d=new SaveFileDialog{Filter=Language.Filter("WAV 32-bit float|*.wav|WAV PCM 16-bit|*.wav"),FileName=(Language.English?"Track-":"Pista-")+(index+1)+".wav"})if(d.ShowDialog(this)==DialogResult.OK){string path=d.FileName;bool floating=d.FilterIndex==1;Background(delegate{Wav.Write(path,clip,floating);},delegate{Engine.Status="Audio de pista exportado sin efectos de reproducción";});}}
  void ExportMix(){if(busy||!CanSave())return;int bars=8;using(Form d=new Form{Text="Exportar mezcla",Size=new Size(420,180),StartPosition=FormStartPosition.CenterParent}){Theme.Style(d);Label l=Theme.Label("Duración de la mezcla en compases:");l.Location=new Point(15,15);d.Controls.Add(l);NumericUpDown n=Theme.Number(1,256,8);n.Location=new Point(20,50);d.Controls.Add(n);Button ok=Theme.Button("Continuar",delegate{d.DialogResult=DialogResult.OK;});ok.Location=new Point(230,80);ok.Width=140;d.Controls.Add(ok);if(d.ShowDialog(this)!=DialogResult.OK)return;bars=(int)n.Value;}using(SaveFileDialog file=new SaveFileDialog{Filter=Language.Filter("Mezcla WAV 32-bit float|*.wav"),FileName=Language.English?"Mix.wav":"Mezcla.wav"})if(file.ShowDialog(this)==DialogResult.OK){string p=file.FileName;Snapshot s=Storage.Capture(Engine);Background(delegate{Wav.RenderMix(p,s,bars);},delegate{Engine.Status="Mezcla exportada con efectos y ritmo";});}}
  void RecordMaster(){if(Audio.Recorder.Recording){Audio.Recorder.Stop();Engine.Status="Grabación máster guardada";return;}if(!Audio.Ready)throw new Exception("Inicia el audio antes de grabar la mezcla.");using(SaveFileDialog d=new SaveFileDialog{Filter=Language.Filter("Máster WAV 32-bit float|*.wav"),FileName="Performance-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".wav"})if(d.ShowDialog(this)==DialogResult.OK)Audio.Recorder.Start(d.FileName);}
  void HandleClosing(object sender,FormClosingEventArgs e){if(busy){UiMessage.Show("Espera a que termine la operación de archivo.");e.Cancel=true;return;}if(!Discard()){e.Cancel=true;return;}closing=true;timer.Stop();Keyboard.ReleaseAll();Audio.Dispose();Midi.Dispose();try{Storage.SaveSystem(Engine.System);}catch{}timer.Dispose();tooltip.Dispose();}
  protected override bool ProcessCmdKey(ref Message msg,Keys keys){if(busy)return true;return base.ProcessCmdKey(ref msg,keys);}
  string RecordingCue(){string ids="",dub="";for(int i=0;i<5;i++){if(Engine.Tracks[i].State==PlayState.Recording)ids+=(ids.Length==0?"":", ")+"P"+(i+1);if(Engine.Tracks[i].State==PlayState.Overdubbing)dub+=(dub.Length==0?"":", ")+"P"+(i+1);}return (ids.Length==0?"":"● GRABANDO "+ids+"   |   ")+(dub.Length==0?"":"● OVERDUB "+dub+"   |   ");}
  public void KeyboardActionCompleted(){status.Text=Language.T(RecordingCue()+Engine.Status);status.Invalidate();status.Update();foreach(TrackStrip strip in strips){strip.Invalidate();strip.Update();}refreshing=true;quantize.Checked=Engine.Config.Quantize;auto.Checked=Engine.Config.AutoRecord;single.Checked=Engine.Config.SinglePlay;countIn.SelectedIndex=Engine.Config.CountInBars;refreshing=false;if(tabs.SelectedIndex==1)rhythmPage.RefreshModel();if(tabs.SelectedIndex==2)fxPage.RefreshModel();}
  public void RunKeyboardAction(string id){switch(id){case "global.start":Engine.AllStart();Midi.Transport(true);break;case "global.stop":Engine.AllStop(false);Midi.Transport(false);break;case "global.panic":Engine.AllStop(true);Midi.Transport(false);break;case "global.tap":Tap();break;case "app.save":Save(false);break;case "app.saveas":Save(true);break;case "app.open":Open();break;case "app.exportmix":ExportMix();break;case "app.masterrecord":RecordMaster();break;case "app.memorynext":memory.Value=Math.Min(99,memory.Value+1);break;case "app.memoryprev":memory.Value=Math.Max(1,memory.Value-1);break;case "app.memoryrecall":RecallMemory((int)memory.Value);break;case "app.memorywrite":WriteMemory();break;case "app.keyboard":ShowOptions();settingsPage.ShowKeyboard();break;case "app.help":ShowMainPage(3);break;case "app.performance":ShowMainPage(0);break;case "app.rhythmpage":ShowMainPage(1);rhythmPage.RefreshModel();break;case "app.fxpage":ShowMainPage(2);fxPage.RefreshModel();break;case "app.trackedit":EditTrack(Engine.Config.SelectedTrack);break;case "app.trackimport":Import(Engine.Config.SelectedTrack);break;case "app.trackexport":Export(Engine.Config.SelectedTrack);break;default:if(id.StartsWith("app.select.")){Engine.Config.SelectedTrack=int.Parse(id.Substring(11));ShowMainPage(0);}else throw new Exception("Acción de programa desconocida.");break;}}
  public const string HelpText="LOOP / FIVE 2\r\n\r\nINICIO RÁPIDO\r\n1. Selecciona tu micrófono y salida en OPCIONES → Dispositivos y pulsa Aplicar. Usa auriculares.\r\n2. Pulsa un círculo o las teclas 1–5: grabar → reproducir → sobregrabar → reproducir.\r\n3. QUANTIZE hace esperar al siguiente compás; desactívalo y desactiva Sync en la pista para tocar libremente.\r\n4. PISTA / WAV abre los ajustes de duración, tempo, reversa, One Shot, bounce, fundidos y archivos.\r\n5. Los botones FX A–D activan efectos. Clic derecho abre el editor. Hay cuatro bancos por sección.\r\n6. RITMOS incluye patrones sintetizados propios, variaciones A–D, 16 kits y un editor de usuario.\r\n7. ESCRIBIR y RECUPERAR usan 99 memorias. ARCHIVO guarda sesiones y exporta mezclas.\r\n8. MASTER graba lo que escuchas, incluyendo efectos y ritmo, a WAV de 32 bits float.\r\n\r\nTECLADO CONFIGURABLE\r\nOpciones → Teclado: selecciona la función y pulsa ASIGNAR TECLA. Ctrl+K abre el editor con el perfil predeterminado. Se guardan los cambios y se pueden exportar perfiles.\r\nLas teclas siguientes son sólo el perfil predeterminado y se pueden cambiar:\r\n1–5: REC / PLAY / DUB. Shift+1–5: STOP. Ctrl+1–5: UNDO.\r\nEspacio: detener todas las pistas. Escape: parada inmediata. R: ritmo. T: tap tempo.\r\nF5–F8: efectos de pista A–D. Ctrl+S: guardar. Ctrl+O: abrir. F1: ayuda.\r\nLos atajos de letras y números no se interceptan al escribir en un campo.\r\n\r\nARCHIVOS\r\nSesiones v2 guardan cinco pistas y todos sus ajustes, efectos y ritmo. Se leen sesiones v1; sus FX de pistas 2–5 no se convierten automáticamente.\r\nWAV: PCM 8/16/24/32 bit o float 32/64 bit, mono/estéreo, 8–192 kHz. Remuestreo lineal a 44.1 kHz.\r\nExportación de pista: audio grabado, sin FX de reproducción. Exportación de mezcla: todas las pistas a la vez con FX y ritmo, desde el inicio.\r\nLímite: 10 minutos por pista y 30 minutos de audio por sesión. Historial de hasta 8 tomas (con límite de memoria) y un punto MARK.\r\n\r\nALCANCE Y DIFERENCIAS\r\nAplicación independiente, sin afiliación con BOSS o Roland. La apariencia y los flujos se inspiran en una loop station de cinco pistas.\r\nLos efectos y los sonidos de batería son desarrollos propios, no los algoritmos, muestras ni patrones del equipo original.\r\nEl tempo con tono conservado usa granos solapados; las voces y la corrección tonal son aproximaciones y pueden tener artefactos. El armonizador MIDI usa la nota activa más reciente; no interpreta acordes completos.\r\nMIDI soporta CC, notas, Program Change, reloj, Start/Stop/Continue y Thru corto; no SysEx ni comunicación propietaria con Tone Studio.\r\nLa entrada y salida son un par estéreo a 44.1 kHz / 16 bits mediante Windows MME; el procesamiento interno y los WAV float son de 32 bits. No hay ASIO ni salidas SUB físicas independientes.\r\nPhantom 48 V, impedancia, conectores y preamplificadores dependen de tu interfaz de audio. No se pueden crear por software.\r\nNo se garantiza equivalencia sonora ni funcional completa con una RC-505mkII. Consulta FUNCIONES.md para el estado detallado.\r\n";
  [STAThread]public static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.ThreadException+=delegate(object s,ThreadExceptionEventArgs e){UiMessage.Show(e.Exception.Message,"LoopFive");};Application.Run(new MainForm());}
 }
